-- PhasePrep development content derived from the current Eglin Phase II portal.
-- Safe to rerun after migrations. No auth users, schedules, private notes, or real evaluations.

begin;

-- Make the baseline migration inserts rerunnable and populate all five 4N0 programs.
insert into public.location_programs (location_id, afsc_program_id, required_hours)
select l.id, a.id, 240
from public.locations l cross join public.afsc_programs a
where a.code = '4N0'
on conflict (location_id, afsc_program_id) do update set required_hours = excluded.required_hours;

insert into public.departments (id, category_id, name, slug, description) values
('10000000-0000-0000-0000-000000000001', (select id from public.department_categories where slug='outpatient-services'), 'Internal Medicine Clinic', 'internal-medicine-clinic', 'Adult disease prevention, diagnosis, treatment, and readiness-focused clinical care.'),
('10000000-0000-0000-0000-000000000002', (select id from public.department_categories where slug='outpatient-services'), 'Neurology Clinic', 'neurology-clinic', 'Neurologic assessment, diagnostic support, and outpatient specialty care.'),
('10000000-0000-0000-0000-000000000003', (select id from public.department_categories where slug='outpatient-services'), 'Orthopedic Clinic', 'orthopedic-clinic', 'Musculoskeletal assessment, treatment support, and procedure preparation.'),
('10000000-0000-0000-0000-000000000004', (select id from public.department_categories where slug='outpatient-services'), 'Dermatology Clinic', 'dermatology-clinic', 'Outpatient skin assessment, minor procedures, and patient education.'),
('10000000-0000-0000-0000-000000000005', (select id from public.department_categories where slug='outpatient-services'), 'General Surgery Clinic', 'general-surgery-clinic', 'Preoperative and postoperative care in the ambulatory setting.'),
('10000000-0000-0000-0000-000000000006', (select id from public.department_categories where slug='outpatient-services'), 'Immunization Clinic', 'immunization-clinic', 'Vaccine preparation, administration support, documentation, and education.'),
('10000000-0000-0000-0000-000000000007', (select id from public.department_categories where slug='outpatient-services'), 'Cardiology Clinic', 'cardiology-clinic', 'Cardiovascular assessment, diagnostics, monitoring, and education.'),
('10000000-0000-0000-0000-000000000008', (select id from public.department_categories where slug='outpatient-services'), 'Flight and Operational Medicine', 'flight-and-operational-medicine', 'Operational readiness, occupational medicine, and flight-focused clinical support.'),
('10000000-0000-0000-0000-000000000009', (select id from public.department_categories where slug='outpatient-services'), 'OB/GYN Clinic', 'ob-gyn-clinic', 'Outpatient reproductive health, preventive care, and procedure support.'),
('10000000-0000-0000-0000-000000000010', (select id from public.department_categories where slug='outpatient-services'), 'Pediatric Clinic', 'pediatric-clinic', 'Outpatient care for infants, children, and adolescents.'),
('10000000-0000-0000-0000-000000000011', (select id from public.department_categories where slug='outpatient-services'), 'Family Medicine Residency Clinic', 'family-medicine-residency-clinic', 'Continuity care across the lifespan in a teaching clinic.'),
('10000000-0000-0000-0000-000000000012', (select id from public.department_categories where slug='outpatient-services'), 'Family Health Clinic', 'family-health-clinic', 'Primary and preventive care for patients across the lifespan.'),
('10000000-0000-0000-0000-000000000013', (select id from public.department_categories where slug='outpatient-services'), 'Warrior Operational Medicine Clinic', 'warrior-operational-medicine-clinic', 'Readiness-centered primary and occupational care.'),
('10000000-0000-0000-0000-000000000014', (select id from public.department_categories where slug='inpatient-services'), 'Labor & Delivery', 'labor-delivery', 'Maternal, fetal, delivery, and immediate postpartum care.'),
('10000000-0000-0000-0000-000000000015', (select id from public.department_categories where slug='inpatient-services'), 'Multi Service Unit', 'multi-service-unit', 'Medical-surgical inpatient care, monitoring, treatment, and recovery support.'),
('10000000-0000-0000-0000-000000000016', (select id from public.department_categories where slug='inpatient-services'), 'Intensive Care Unit', 'intensive-care-unit', 'Continuous monitoring and advanced multidisciplinary care for critically ill patients.'),
('10000000-0000-0000-0000-000000000017', (select id from public.department_categories where slug='inpatient-services'), 'Operating Room', 'operating-room', 'Perioperative safety, sterile technique, and surgical team workflows.'),
('10000000-0000-0000-0000-000000000018', (select id from public.department_categories where slug='inpatient-services'), 'Ambulatory Surgical Unit', 'ambulatory-surgical-unit', 'Same-day surgical preparation, recovery, and discharge support.'),
('10000000-0000-0000-0000-000000000019', (select id from public.department_categories where slug='emergency-services'), 'Emergency Room', 'emergency-room', 'Rapid assessment, stabilization, emergency procedures, and team-based care.')
on conflict (slug) do update set name=excluded.name, category_id=excluded.category_id, description=excluded.description;

-- Eglin is the first fully populated location. Other sites remain configurable records.
insert into public.location_departments (location_program_id, department_id, display_name, required_hours, overview, is_active)
select lp.id, d.id, d.name,
  case when d.slug='emergency-room' then 48 when d.slug in ('multi-service-unit','intensive-care-unit','labor-delivery') then 32 else 0 end,
  case d.slug
    when 'ambulatory-surgical-unit' then 'The Ambulatory Surgical Unit (ASU) provides same‑day surgical care for patients undergoing outpatient procedures that do not require overnight hospitalization. The unit supports a wide range of minor to moderate surgical specialties, including general surgery, orthopedics, ENT, gynecology, and dermatologic procedures. Patients are admitted, prepared, operated on, and discharged within the same day, making efficiency, safety, and coordinated teamwork essential. Staff members include surgeons, anesthesiologists, CRNAs, nurses, surgical technicians, and administrative personnel who work together to ensure smooth transitions through pre‑operative, intra‑operative, and post‑operative phases. Students rotating in the ASU gain exposure to pre‑operative assessments, vital‑sign collection, patient education, and assisting staff with preparing patients for surgery. They also observe sterile technique, surgical workflow, and post‑anesthesia recovery processes. In the PACU, students learn how to monitor airway status, pain levels, nausea, and vital signs while supporting safe discharge criteria. The ASU emphasizes patient safety, infection control, and efficient perioperative care, giving students a strong foundation in outpatient surgical operations and interdisciplinary teamwork.'
    when 'cardiology-clinic' then 'The Cardiology Clinic provides specialized evaluation and management of cardiovascular conditions, offering comprehensive care for patients with hypertension, arrhythmias, coronary artery disease, heart failure, lipid disorders, and other cardiac concerns. The clinic performs diagnostic testing such as EKGs, echocardiograms, stress testing, and routine cardiac monitoring to support accurate diagnosis and treatment planning. Staff members include cardiologists, nurse practitioners, nurses, technicians, and support personnel who work together to provide patient‑centered, evidence‑based care. Students rotating in the Cardiology Clinic gain exposure to cardiac assessments, vital‑sign interpretation, medication review for cardiac conditions, and assisting with diagnostic procedures. They also learn how to recognize red‑flag symptoms such as chest pain, shortness of breath, palpitations, and edema, and how to communicate findings effectively to providers. The clinic emphasizes prevention, early detection, and long‑term management, giving students a strong foundation in cardiovascular health and the importance of coordinated, detail‑oriented care.'
    when 'dermatology-clinic' then 'The Dermatology Clinic provides comprehensive evaluation and treatment of skin, hair, and nail conditions for patients of all ages. The clinic manages a wide range of concerns, including acne, eczema, psoriasis, rashes, skin infections, benign lesions, and skin cancer screenings. Providers also perform minor procedures such as biopsies, cryotherapy, wart removal, and follow‑up care for treated lesions. Staff members include dermatologists, physician assistants, nurses, and medical technicians who work together to deliver accurate diagnoses, effective treatments, and patient‑centered education. Students rotating in the Dermatology Clinic gain experience with skin assessments, lesion identification, cryotherapy assistance, and supporting providers during biopsies and minor procedures. They also learn how to document dermatologic findings using proper terminology, recognize urgent dermatologic conditions, and educate patients on skin care, sun protection, and follow‑up needs. The clinic emphasizes precision, early detection, and preventive care, giving students a strong foundation in outpatient dermatology and hands‑on experience with common skin conditions.'
    when 'family-health-clinic' then 'The Family Health Clinic provides comprehensive primary care services for adult patients, focusing on preventive medicine, chronic disease management, acute illness evaluation, and routine health maintenance. The clinic supports a diverse patient population and offers services such as annual physicals, women’s health visits, medication management, immunizations, and follow‑up care for long‑term conditions like hypertension, diabetes, and asthma. Staff members include physicians, nurse practitioners, physician assistants, nurses, technicians, and administrative personnel who work together to ensure efficient, patient‑centered care. Students rotating in the Family Health Clinic gain experience with vital‑sign collection, patient intake, medication reconciliation, and assisting providers during exams or minor procedures. They also learn how to communicate effectively with adult patients, identify red‑flag symptoms, and document encounters accurately in the electronic medical record. The clinic emphasizes continuity of care, teamwork, and preventive health, giving students a strong foundation in outpatient medicine and the skills needed to support patients in maintaining long‑term wellness.'
    when 'flight-and-operational-medicine' then 'The Flight and Operational Medicine Clinic is located in Building 2750 next to Public Health, with office and staff hours from 0700–1600 Monday through Friday, closing at 1200 on Wednesdays for training. Its primary mission is to provide preventive and operational medical care to the flying population and their families. On a typical day, the clinic sees up to 50 patients. During the rotation, students are introduced to a wide range of duties, including screening and checking in patients, computerized appointment booking and validation, monitoring and recording physiological measurements, performing initial triage, and managing patient flow into treatment rooms. Students may also assist with medical tasks directed by the Flight Surgeon, prepare and administer medications under supervision, perform paraprofessional portions of physical exams, and help assemble, operate, and maintain therapeutic equipment. Additional responsibilities include maintaining treatment and exam rooms, performing basic life support, managing health record systems such as CHCS and PIMR, and notifying flying or special‑operations squadrons of personnel placed in Duty Not to Include Flying (DNIF) status. The clinic also supports human‑factor evidence collection, mishap response, and provides primary medical support for in‑flight emergencies, aircraft mishap investigations, and natural disasters.'
    when 'general-surgery-clinic' then 'The General Surgery Clinic provides evaluation, management, and follow‑up care for patients requiring surgical consultation or postoperative monitoring. The clinic addresses a wide range of conditions, including hernia evaluations, gallbladder disease, abdominal pain, skin and soft‑tissue masses, wound checks, and postoperative concerns such as pain, infection risk, or healing complications. Providers perform minor in‑clinic procedures such as suture and staple removal, incision and drainage, and follow‑up assessments after major surgeries. Staff members include surgeons, physician assistants, nurses, and medical technicians who work together to ensure safe pre‑operative planning, efficient postoperative care, and clear communication with patients. Students rotating in the General Surgery Clinic gain experience with pre‑operative assessments, vital‑sign interpretation, wound evaluation, and assisting providers during minor procedures. They also learn how to identify red‑flag symptoms such as fever, increasing pain, drainage, or signs of dehiscence, and how to document surgical follow‑up visits accurately. The clinic emphasizes safety, precision, and continuity of care, giving students a strong foundation in outpatient surgical management and interdisciplinary teamwork.'
    when 'immunization-clinic' then 'The Immunization Clinic provides comprehensive vaccine services for patients of all ages, focusing on preventive health and protection against communicable diseases. The clinic administers routine childhood vaccines, adult immunizations, travel vaccines, seasonal influenza shots, and readiness‑related vaccines for active‑duty personnel. Staff members include nurses, medical technicians, and administrative personnel who work together to ensure safe vaccine storage, accurate documentation, and efficient patient flow. Students rotating in the Immunization Clinic gain experience with vaccine preparation, screening for contraindications, injection techniques, and patient education regarding expected side effects and follow‑up care. They also learn how to review immunization records, maintain cold‑chain standards, and document vaccines in electronic medical systems. The clinic emphasizes safety, accuracy, and preventive care, giving students a strong foundation in public health and immunization practices.'
    when 'intensive-care-unit' then 'The Intensive Care Unit (ICU) is located on the third floor of the main hospital building and operates 24 hours a day, 7 days a week, ensuring continuous, high-quality critical care. Staffed by a multidisciplinary team of 16 registered nurses, 2 paramedics, and 11 medical technicians, the ICU features 7 patient rooms equipped with advanced monitoring and life-support systems, as well as a dedicated training room to support ongoing staff education and simulation exercises. The ICU team is highly skilled in the management of critically ill patients, providing comprehensive care that includes advanced airway management such as endotracheal intubation and ventilator support, insertion and management of arterial lines and central venous catheters, hemodynamic monitoring and titration of vasoactive medications, blood draws and laboratory specimen collection, ultrasound-guided intravenous (IV) access, insertion and care of foley catheters and other indwelling devices, blood glucose monitoring and insulin administration, medication administration including continuous infusions and emergency drugs, wound care, pressure injury prevention, and continuous cardiac and respiratory monitoring. ICU staff are trained to respond promptly to all hospital emergency codes, including adult and pediatric code (cardiac/respiratory arrest), and other critical events, providing rapid assessment and intervention as part of the hospital’s emergency response team. Medical technicians are responsible for continuous telemetry monitoring for patients in the ICU, as well as for those in the Medical-Surgical Unit (MSU) and Labor & Delivery (L&D) units, which includes real-time surveillance of cardiac rhythms, prompt identification of arrhythmias, and immediate notification of the clinical team regarding any significant changes. Additionally, the ICU at Eglin supports postoperative care for high-risk surgical patients, management of sepsis and multi-organ dysfunction, and coordination with multidisciplinary teams such as respiratory therapy, pharmacy, and nutrition services, while also providing family support and patient education. The ICU is committed to maintaining the highest standards of patient safety, clinical excellence, and compassionate care!'
    when 'internal-medicine-clinic' then 'Internal Medicine is a dynamic specialty focused on the prevention, diagnosis, and treatment of adult diseases, led by highly trained Internists who manage everything from chronic conditions to complex multi‑system concerns. Within the clinic, technicians play a crucial role in delivering seamless, compassionate care by booking appointments, supporting telephone consults, performing blood glucose testing, completing 3‑ and 5‑day blood pressure checks, administering vitamin B‑12 injections, starting IVs, and assisting with well‑woman exams. The clinic’s treatment room serves as a controlled, readiness‑focused space where critical patients can be evaluated, stabilized, and monitored using IV therapy, fluids, and emergency equipment when needed. Even routine tasks like patient check‑ins become meaningful opportunities to build trust, understand concerns, and show patients that their health truly matters.'
    when 'labor-delivery' then 'Labor and Delivery is a specialized unit dedicated to providing comprehensive care for expectant mothers throughout labor, childbirth, and the immediate postpartum period. The clinic’s mission focuses on ensuring safe deliveries, monitoring maternal and fetal well‑being, and supporting families through one of the most important moments of their lives. Patients are assessed upon arrival for labor progression, fetal status, and any urgent needs, and are then guided through the appropriate level of care, whether routine monitoring, induction, or emergency intervention. Staff members work collaboratively to perform duties such as patient triage, fetal monitoring, vital‑sign assessment, medication administration, and assisting providers during vaginal deliveries or cesarean sections. Students rotating in Labor and Delivery gain exposure to the birthing process, newborn assessments, postpartum care, and the importance of communication and emotional support during high‑stress situations. The unit also maintains readiness for obstetric emergencies, including hemorrhage, preeclampsia, and fetal distress, ensuring rapid response and coordinated teamwork. Overall, Labor and Delivery offers a fast‑paced, hands‑on learning environment centered on safety, compassion, and family‑centered care.'
    when 'multi-service-unit' then 'The Medical Surgical Unit (MSU) is a fast‑paced inpatient unit that provides comprehensive care for patients recovering from surgery, managing acute medical conditions, or requiring close monitoring during hospitalization. The unit supports a wide range of diagnoses, including post‑operative recovery, respiratory illnesses, cardiac conditions, infections, and chronic disease exacerbations. Staff members work collaboratively to assess patients, administer medications, monitor vital signs, manage IV therapy, perform wound care, and assist with mobility and daily needs. Students rotating through MSU gain exposure to patient assessments, charting, medication administration under supervision, and the importance of time management in a high‑acuity environment. They also learn how to support nurses and providers during procedures, respond to changes in patient status, and communicate effectively with patients and families. The MSU emphasizes safety, teamwork, and continuous monitoring, making it an essential learning environment for understanding inpatient care and the coordination required to support patients through recovery.'
    when 'neurology-clinic' then 'The Neurology Clinic is located on the third floor of the Eglin Outpatient Hospital. Our duty hours are 0700-1600 Monday-Friday. We currently have 2 procedure rooms. Clinic attire consists of the uniform of the day. We have 6 staff members including one Nurse, five Technologist, and two Neurologists. Our primary mission is to treat a wide range of patients with underlying neurological ailments to include traumatic brain injury, epilepsy, neuropathies, and neurologic degeneration disorders. We hold patient care in great regard. Most procedures are performed during scheduled appointments, however, care is also provided within the ICUs and wards. While rotating through the Neurology Clinic, the Medical Technician''s primary duties include: meeting patients, explaining the sequence of events that the patient can expect before and after the procedure, preparing the patient for the desired exam, and performing appropriate medical documentation. We average procedures a month in the areas of electroencephalography, nerve conduction studies, and evoked potentials. Additionally, we assist neurologists in the performance of electromyography. We see patients in the outpatient and inpatient setting with emergency cases added on as needed. We primarily see adult patients. There is a wide range of training opportunities in the Neurology Clinic and many ways to enhance your knowledge as a Medical Technician.'
    when 'ob-gyn-clinic' then 'The OB/GYN Clinic provides comprehensive women’s health services focused on reproductive care, prenatal and postpartum management, gynecologic evaluations, and preventive screenings. The clinic supports patients across all stages of life, offering routine well‑woman exams, Pap smears, contraception counseling, fertility evaluations, prenatal visits, and management of common gynecologic conditions such as pelvic pain, menstrual disorders, and infections. Providers include obstetricians, gynecologists, nurse practitioners, nurses, and medical technicians who work together to deliver patient‑centered, confidential, and compassionate care. Students rotating in the OB/GYN Clinic gain exposure to vital‑sign collection, patient intake, prenatal assessments, and assisting providers during pelvic exams or minor procedures. They also learn how to support sensitive conversations, maintain patient privacy, and recognize red‑flag symptoms that require urgent evaluation. The clinic emphasizes education, preventive care, and early detection, giving students a strong foundation in women’s health and the importance of holistic, respectful communication.'
    when 'operating-room' then 'The Operating Room (OR) is a highly controlled, fast‑paced environment dedicated to providing surgical care for a wide range of procedures, from routine outpatient surgeries to complex orthopedic, general, and emergency operations. The OR team works collaboratively to ensure patient safety before, during, and after surgery through precise coordination, sterile technique, and constant communication. Staff members include surgeons, anesthesiologists, nurse anesthetists, circulating nurses, scrub technicians, and support personnel who maintain equipment, prepare surgical instruments, and assist throughout each procedure. Students rotating in the OR gain exposure to sterile field setup, surgical instrumentation, patient positioning, anesthesia preparation, and the workflow required to maintain a safe operative environment. They also observe how the team responds to unexpected changes in patient status, manages surgical counts, and follows strict infection‑control protocols. The OR emphasizes discipline, teamwork, and attention to detail, offering students a valuable opportunity to understand the technical and procedural foundation of surgical care.'
    when 'orthopedic-clinic' then 'The orthopedic clinic is located on the first floor at the south end of the building, opposite the ER waiting area, and operates from 0700–1600 Monday through Friday. It is a referral‑only clinic that provides outpatient musculoskeletal care for approximately 83,000 eligible beneficiaries, including active‑duty members, VA patients, retirees, and their families, with more than 12,000 appointments annually. The clinic staff includes 14 technicians, 1 nurse, 4 physician assistants, 1 podiatrist, 1 orthopedic spine specialist, and 6 orthopedic surgeons. Orthopedic technicians perform duties such as applying and removing casts and splints, assisting providers with exams and minor procedures, preparing prescriptions in the operating room suite, and coordinating patient care. They also maintain skills in surgical instrumentation setup, medical database use, and medical records processing. During the rotation, students learn proper casting and splinting techniques, when each method is appropriate, and how to support providers during procedures. The clinic also performs platelet‑rich plasma (PRP) therapy, a process in which a patient’s blood is drawn, spun in a centrifuge to separate the plasma, and then injected into targeted areas to promote healing.'
    when 'pediatric-clinic' then 'The Pediatric Clinic provides comprehensive outpatient care for infants, children, and adolescents, focusing on preventive health, acute illness management, and long‑term monitoring of developmental and chronic conditions. The clinic supports families by offering well‑child visits, immunizations, sick‑call evaluations, growth and developmental screenings, and management of common childhood concerns such as respiratory infections, asthma, allergies, and behavioral or nutritional issues. Staff members work collaboratively to create a child‑friendly environment that reduces anxiety and encourages trust during examinations and procedures. Students rotating in pediatrics gain exposure to age‑specific assessment techniques, communication strategies tailored to children and parents, and clinical tasks such as vital‑sign collection, growth measurements, vaccine preparation, and assisting providers during exams. They also learn how to recognize red‑flag symptoms, support families through education, and maintain safety and infection‑control standards in a high‑volume setting. Overall, the Pediatric Clinic offers a hands‑on learning experience centered on compassion, patience, and developmentally appropriate care.'
    when 'emergency-room' then 'The Emergency Room provides rapid assessment, stabilization, and treatment for patients presenting with urgent and emergent medical conditions, from minor injuries to life‑threatening trauma and critical illness. The department operates around the clock, triaging patients by acuity and coordinating closely with inpatient units, surgery, and specialty consultants to ensure timely, appropriate care. Staff members include emergency physicians, nurses, medical technicians, and support personnel who work together under significant time pressure to identify and address the most urgent needs first. Students rotating in the Emergency Room gain exposure to rapid patient assessment, vital‑sign monitoring, wound care, IV therapy, and assisting providers during emergent procedures. They also learn how to prioritize competing demands, communicate concisely under pressure, and document care accurately in a fast‑changing environment. The Emergency Room emphasizes situational awareness, teamwork, and adaptability, giving students a strong foundation in acute and emergency care.'
    when 'family-medicine-residency-clinic' then 'The Family Medicine Residency Clinic provides continuity primary care across the lifespan while also serving as a teaching clinic for physicians in residency training. The clinic manages preventive care, chronic disease management, acute illness, and coordinated referrals, offering patients a consistent care team over time. Staff members include resident physicians, attending faculty, nurses, and medical technicians who work together to balance patient care with hands‑on medical education. Students rotating in the Family Medicine Residency Clinic gain experience with vital‑sign collection, patient intake, chart review, and assisting providers during exams and follow‑up visits. They also observe how resident physicians are supervised and mentored, and how care plans are adjusted over successive visits for the same patient. The clinic emphasizes continuity of care, teaching, and collaborative decision‑making, giving students insight into both patient care and clinical education.'
    when 'warrior-operational-medicine-clinic' then 'The Warrior Operational Medicine Clinic (WOMC) provides readiness‑focused primary and occupational care for active‑duty members, with an emphasis on maintaining medical readiness for deployment and daily mission requirements. The clinic manages routine and acute care, occupational health concerns, and readiness‑related evaluations, coordinating closely with unit leadership and other specialty clinics when needed. Staff members include providers, nurses, and medical technicians who work together to keep the force healthy and mission‑ready. Students rotating in the WOMC gain experience with vital‑sign collection, patient intake, readiness‑related documentation, and assisting providers during exams and procedures. They also learn how occupational and operational factors influence care decisions, and how to support a population whose primary concern is often fitness for duty rather than routine illness. The WOMC emphasizes readiness, efficiency, and mission‑focused care, giving students a strong foundation in operational medicine.'
    else d.description
  end,
  true
from public.location_programs lp
join public.locations l on l.id=lp.location_id and l.installation_code='EGLIN'
join public.afsc_programs a on a.id=lp.afsc_program_id and a.code='4N0'
cross join public.departments d
on conflict (location_program_id, department_id) do update
set display_name=excluded.display_name, required_hours=excluded.required_hours, overview=excluded.overview, is_active=true;

insert into public.department_procedures
(id, location_department_id, name, slug, what_it_is, why_it_is_used, how_it_works, student_learning_objectives, equipment, external_resource_url, video_url, sort_order, status, reviewed_at)
values
('20000000-0000-0000-0000-000000000001', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='internal-medicine-clinic'), 'Peripheral IV Insertion', 'peripheral-iv-insertion', 'Placement of a small catheter into a peripheral vein.', 'Provides direct bloodstream access for fluids, medications, contrast, and stabilization.', 'A suitable vein is identified, the area is cleansed, the catheter is advanced, secured, flushed, and monitored for patency and complications.', 'Observe vein selection, aseptic technique, patient communication, safety checks, documentation, and recognition of infiltration or phlebitis.', 'Gloves, tourniquet, antiseptic, IV catheter, saline flush, extension tubing, transparent dressing, tape, and sharps container.', 'https://www.ncbi.nlm.nih.gov/books/NBK539795/', 'https://youtu.be/W4_9louZ4OU', 1, 'published', now()),
('20000000-0000-0000-0000-000000000002', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='intensive-care-unit'), 'Central Venous Catheter Insertion', 'central-venous-catheter-insertion', 'Placement of a large IV catheter into a central vein.', 'Supports multiple infusions, vasopressors, parenteral nutrition, and central venous monitoring.', 'Under sterile conditions and commonly ultrasound guidance, a guidewire and dilator are used to place and secure the catheter.', 'Recognize sterile technique, ultrasound-guided access, central-line handling, and infection-prevention practices.', 'CVC kit, sterile barriers, ultrasound and probe cover, chlorhexidine, flushes, sutures, and sterile dressing.', 'https://www.ncbi.nlm.nih.gov/books/NBK557798/', 'https://youtu.be/zBv4JuueLHk', 1, 'published', now()),
('20000000-0000-0000-0000-000000000003', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='labor-delivery'), 'Epidural Analgesia', 'epidural-analgesia', 'Administration of local anesthetic into the epidural space for labor analgesia.', 'Provides significant pain relief during labor while the patient remains awake and responsive.', 'The patient is positioned, the lower back is prepared using sterile technique, a catheter is placed, and medication is infused with continued maternal and fetal monitoring.', 'Observe patient positioning, sterile-field maintenance, maternal blood-pressure monitoring, fetal monitoring, and pain assessment.', 'Epidural kit, sterile preparation and drapes, local anesthetic, infusion pump, fetal monitor, and blood-pressure cuff.', 'https://www.ncbi.nlm.nih.gov/books/NBK542219/', 'https://youtu.be/2tw-SXI3wKU', 1, 'published', now()),
('20000000-0000-0000-0000-000000000004', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='multi-service-unit'), 'Wound Care Dressing Change', 'wound-care-dressing-change', 'Cleaning, assessment, and redressing of a wound or surgical incision.', 'Promotes healing, reduces infection risk, and supports early recognition of complications.', 'The old dressing is removed, the wound is assessed and cleansed, prescribed treatment is applied, and a new sterile dressing is secured.', 'Practice preparation, sterile technique, wound assessment, disposal, documentation, and identification of infection or delayed healing.', 'Gloves, sterile dressing kit, cleansing solution, gauze, tape, wound measurement supplies, ordered treatments, and biohazard disposal.', 'https://www.ncbi.nlm.nih.gov/books/NBK470199/', 'https://youtu.be/5Cid7q9_Uq0', 1, 'published', now()),
('20000000-0000-0000-0000-000000000005', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='cardiology-clinic'), 'Electrocardiogram (EKG/ECG)', 'electrocardiogram-ekg-ecg', 'A painless, noninvasive test that records the electrical signals of the heart.', 'Used to detect arrhythmias, coronary artery disease, and evidence of a prior heart attack.', 'Electrode patches are placed on the chest, arms, and legs and connected to a recording machine that captures the heart''s twelve-lead electrical tracing for the provider to interpret.', 'Practice 12-lead setup, patient preparation, machine operation, and basic rhythm interpretation.', 'EKG machine, electrodes, and skin-prep supplies.', 'https://www.heart.org/en/health-topics/heart-attack/diagnosing-a-heart-attack/electrocardiogram', 'https://youtu.be/p_eOL7uy40M', 1, 'published', now()),
('20000000-0000-0000-0000-000000000006', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='dermatology-clinic'), 'Skin Biopsy', 'skin-biopsy', 'A procedure to remove a small sample of skin for testing.', 'Used to diagnose skin conditions including malignancies, infections, and inflammatory disorders.', 'Local anesthetic is applied, then tissue is removed via scalpel, punch tool, or blade, and the sample is sent for laboratory analysis.', 'Practice anesthetic administration, biopsy technique, suturing, and post-procedure wound management.', 'Lidocaine, syringes, biopsy punch or scalpel, forceps, sutures, sterile drapes, and specimen containers.', 'https://www.ncbi.nlm.nih.gov/books/NBK470457/', 'https://youtube.com/shorts/VUE5lRcR5Hk', 1, 'published', now()),
('20000000-0000-0000-0000-000000000007', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='general-surgery-clinic'), 'Appendectomy', 'appendectomy', 'The surgical removal of the appendix.', 'Performed to treat appendicitis, an infection or inflammation of the appendix that can be life-threatening if it bursts.', 'The procedure can be performed via open surgery (a single larger incision) or laparoscopically (several small incisions with camera guidance); the appendix is ligated, severed from the intestine, and removed.', 'Practice pre-operative diagnostic assessment, sterile surgical preparation, OR assistance, and post-operative pain management.', 'Scalpels, retractors, laparoscopic instruments, sutures, staplers, and sterile dressings.', 'https://www.facs.org/for-patients/the-day-of-your-surgery/appendectomy/', 'https://youtu.be/MAppEy9Umcg', 1, 'published', now()),
('20000000-0000-0000-0000-000000000008', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='immunization-clinic'), 'Intramuscular (IM) Vaccine Administration', 'intramuscular-im-vaccine-administration', 'The injection of a vaccine directly into a muscle, typically the deltoid in adults or the anterolateral thigh in infants.', 'Delivers vaccines with rapid absorption through the muscle''s rich blood supply.', 'The provider identifies the anatomical landmark, cleans the site with an alcohol swab, inserts the needle at a 90-degree angle, injects the vaccine steadily, and withdraws the needle quickly.', 'Practice anatomical landmarking, needle selection, safe injection technique, and post-vaccination observation.', 'Vaccine vial or prefilled syringe, needles, alcohol swabs, cotton balls or gauze, bandages, and a sharps container.', 'https://www.cdc.gov/vaccines/hcp/admin/admin-protocols.html', 'https://youtube.com/shorts/kf1BAr6o-a8', 1, 'published', now()),
('20000000-0000-0000-0000-000000000009', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='neurology-clinic'), 'Botox Injections (Neurology)', 'botox-injections-neurology', 'Botox is a medication that may be injected into specific muscles to reduce unwanted muscle activity or spasms.', 'Addresses muscle stiffness, chronic migraines, and nerve-related movement disorders in neurological contexts.', 'Botox acts by blocking the release of pain-triggering chemicals and neurotransmitters from overactive nerves at the injection site.', 'Observe patient preparation, provider explanation, injection technique, safety protocols, and patient education.', 'Gloves, antiseptic wipes, syringes, needles, medication vials, sharps container, and documentation tools.', 'https://www.ncbi.nlm.nih.gov/books/NBK557387/', 'https://youtu.be/1FbyUn3OZx4', 1, 'published', now()),
('20000000-0000-0000-0000-000000000010', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='ambulatory-surgical-unit'), 'Outpatient Knee Arthroscopy', 'outpatient-knee-arthroscopy', 'A minimally invasive surgical procedure used to diagnose and treat problems in the knee joint.', 'Addresses a torn meniscus, ACL reconstruction needs, or removal of loose bone or cartilage fragments.', 'The procedure involves small incisions, insertion of an arthroscope for visualization, and use of specialized instruments through additional portals.', 'Practice pre-operative assessment, sterile field setup, equipment preparation, and discharge criteria.', 'Arthroscope, light source, camera system, fluid management system, arthroscopic shavers/biters, sterile drapes, and anesthesia supplies.', 'https://www.orthoinfo.org/en/treatment/knee-arthroscopy/', 'https://youtube.com/shorts/CMluZihlfCc', 1, 'published', now()),
('20000000-0000-0000-0000-000000000011', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='flight-and-operational-medicine'), 'Aviation Medical Examination (Flight Physical)', 'aviation-medical-examination-flight-physical', 'A comprehensive physical and mental health assessment required for pilots and aircrew to ensure they are fit to fly.', 'Identifies medical conditions that could affect pilot safety and operational capability.', 'The exam includes medical history review, a physical exam with vision and hearing tests, cardiovascular assessment via EKG, neurological checks, and potential psychological screening.', 'Learn aviation medicine regulations, specialized vision testing, occupational health screening, and altitude physiology effects.', 'Snellen chart, Ishihara color vision plates, audiometer, sphygmomanometer, stethoscope, ophthalmoscope, and EKG machine.', 'https://www.faa.gov/ame_guide/app_process/exam_tech/item52', 'https://youtu.be/6m2RYTNpB3A', 1, 'published', now()),
('20000000-0000-0000-0000-000000000012', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='ob-gyn-clinic'), 'Pap Smear and Pelvic Exam', 'pap-smear-and-pelvic-exam', 'A screening test for cervical cancer that involves collecting cells from the cervix.', 'Detects precancerous or cancerous cervical cells early, allowing for effective treatment.', 'The patient is positioned on the exam table with feet in stirrups; a speculum is inserted to visualize the cervix; a brush or spatula collects cells, which are sent to a lab.', 'Practice patient communication, speculum use, sample collection, and screening guidelines.', 'Exam table with stirrups, speculum, cervical brush or spatula, specimen container, lubricant, gloves, and light source.', 'https://www.acog.org/womens-health/faqs/cervical-cancer-screening', 'https://youtu.be/8HvHqp_hQic', 1, 'published', now()),
('20000000-0000-0000-0000-000000000013', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='pediatric-clinic'), 'Automated Vision Screening (Photoscreener)', 'automated-vision-screening-photoscreener', 'A quick, noninvasive test that uses a handheld or tabletop device to assess a child''s eyesight by analyzing how their eyes focus and reflect light.', 'Detects vision problems including nearsightedness, farsightedness, astigmatism, amblyopia risk, and eye misalignment, particularly useful for young children who can''t read an eye chart.', 'The child focuses on a target such as a blinking light or sound cue inside the device, which captures measurements via retinal light reflection and generates a pass or referral result.', 'Practice proper child positioning, device operation, result interpretation, parent communication, and accurate documentation.', 'Automated vision screener (photoscreener or autorefractor), disinfectant wipes, documentation tools, and referral forms.', 'https://www.ncbi.nlm.nih.gov/books/NBK487841/', 'https://youtu.be/kuMGJA9XMJQ', 1, 'published', now()),
('20000000-0000-0000-0000-000000000014', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='family-medicine-residency-clinic'), 'Incision and Drainage (I&D) of an Abscess', 'incision-and-drainage-of-an-abscess', 'A minor surgical procedure to release pus or pressure that has built up under the skin.', 'Used to manage skin abscesses, boils, or infected cysts that don''t respond to antibiotics alone.', 'The site is cleaned and numbed with local anesthetic, a small incision is made over the abscess to allow drainage, and the wound may be packed with sterile gauze.', 'Practice distinguishing an abscess from cellulitis, applying local anesthesia, maintaining incision safety, and managing wound packing.', 'Local anesthetic (lidocaine), syringes and needles, a #11 scalpel blade, hemostats, sterile gauze or packing strips, culture swabs, and bandages.', 'https://www.ncbi.nlm.nih.gov/books/NBK556072/', 'https://youtu.be/PUFWezwT6f0', 1, 'published', now()),
('20000000-0000-0000-0000-000000000015', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='family-health-clinic'), 'Blood Pressure Measurement', 'blood-pressure-measurement', 'Measurement of the force of blood against the artery walls using a blood pressure cuff and stethoscope or an automated device.', 'A core vital sign used to screen for hypertension and hypotension and to guide medication and treatment decisions at nearly every visit.', 'A properly sized cuff is placed on the upper arm at heart level, inflated above the expected systolic pressure, and slowly deflated while the provider auscultates or the automated device detects the systolic and diastolic readings.', 'Practice correct cuff sizing and placement, manual auscultation technique, and recognition of abnormal readings requiring provider escalation.', 'Sphygmomanometer (manual or automated), stethoscope, and appropriately sized cuffs.', 'https://www.ncbi.nlm.nih.gov/books/NBK553213/', 'https://youtu.be/Q_N8Qi44ojQ', 1, 'published', now()),
('20000000-0000-0000-0000-000000000016', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='warrior-operational-medicine-clinic'), 'Readiness Intake Assessment', 'readiness-intake-assessment', 'A structured intake evaluation performed when an active-duty member is seen for readiness or occupational health concerns.', 'Confirms the member''s medical readiness status and documents findings needed for periodic health assessments and duty determinations.', 'Vital signs and a focused history are collected, occupational and readiness-related questions are reviewed, and findings are documented in the appropriate readiness system.', 'Practice structured intake interviewing, vital-sign collection, and readiness-focused documentation.', 'Vital-sign equipment, intake questionnaire, and access to PIMR and readiness documentation systems.', 'https://www.ncbi.nlm.nih.gov/books/NBK493211/', 'https://www.dvidshub.net/video/806872/periodic-health-assessment', 1, 'published', now()),
('20000000-0000-0000-0000-000000000017', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='operating-room'), 'Laparoscopic Cholecystectomy', 'laparoscopic-cholecystectomy', 'Minimally invasive surgical removal of the gallbladder.', 'Addresses gallstones, gallbladder inflammation, or biliary dyskinesia.', 'Small abdominal incisions are made, the abdomen is inflated with CO2 gas, and a laparoscope with instruments is inserted to dissect and remove the gallbladder.', 'Practice OR sterile setup, surgical scrubbing and gowning, laparoscopic equipment operation, basic surgical anatomy, and safe tissue handling.', 'Laparoscopic tower, laparoscope, trocars, graspers, clip appliers, an electrocautery device, and a specimen retrieval bag.', 'https://www.facs.org/for-patients/the-day-of-your-surgery/cholecystectomy/', 'https://youtu.be/ffoKThdqo4I', 1, 'published', now()),
('20000000-0000-0000-0000-000000000018', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='orthopedic-clinic'), 'Platelet-Rich Plasma (PRP) Therapy', 'platelet-rich-plasma-prp-therapy', 'A procedure in which a small amount of the patient''s blood is drawn and processed in a centrifuge to separate and concentrate the plasma and platelets.', 'Used to treat chronic joint pain, tendon injuries, inflammation, and slow-healing soft-tissue problems through growth factors that support tissue repair.', 'Blood is collected, spun in a centrifuge to separate the plasma, and then injected into the affected area under sterile technique.', 'Observe blood collection, centrifuge setup, sterile preparation, injection technique, patient education, and post-procedure care.', 'Gloves, antiseptic wipes, syringes, needles, centrifuge tubes, a centrifuge machine, PRP collection kits, a sharps container, and documentation tools.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11499309/', 'https://youtu.be/NxW4dPcNRBM', 1, 'published', now()),
('20000000-0000-0000-0000-000000000019', (select ld.id from public.location_departments ld join public.departments d on d.id=ld.department_id join public.location_programs lp on lp.id=ld.location_program_id join public.locations l on l.id=lp.location_id where l.installation_code='EGLIN' and d.slug='emergency-room'), 'Endotracheal Intubation', 'endotracheal-intubation', 'Placement of a flexible plastic tube into the trachea to maintain an open airway.', 'Used to protect the airway and provide oxygenation or ventilation support during severe illness, trauma, or cardiac arrest.', 'A laryngoscope is used to visualize the vocal cords, the tube is passed through them into the trachea, the cuff is inflated, and placement is confirmed via auscultation and capnography.', 'Practice airway assessment, rapid-sequence intubation pharmacology, equipment preparation, and post-intubation care.', 'Laryngoscope (Mac or Miller blade), endotracheal tubes, a stylet or bougie, a bag-valve-mask, suction setup, and a capnography monitor.', 'https://www.ncbi.nlm.nih.gov/books/NBK470403/', 'https://youtu.be/lIujb6fl5XA', 1, 'published', now())
on conflict (id) do update set name=excluded.name, what_it_is=excluded.what_it_is, why_it_is_used=excluded.why_it_is_used, how_it_works=excluded.how_it_works, student_learning_objectives=excluded.student_learning_objectives, equipment=excluded.equipment, external_resource_url=excluded.external_resource_url, video_url=excluded.video_url, status='published', reviewed_at=now();

