insert into public.handbooks (id,afsc_program_id,location_id,title,slug,version_label,effective_from,status) values
('50000000-0000-0000-0000-000000000001',(select id from public.afsc_programs where code='4N0'),(select id from public.locations where installation_code='EGLIN'),'AMSA Phase II Student Handbook','amsa-phase-ii-student-handbook','Current Webflow Edition',current_date,'published')
on conflict (id) do update set status='published';

insert into public.handbook_sections (id,handbook_id,heading,body,sort_order,section_group,table_data) values
('51000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','Introduction Overview','This course, J5AB04NO31-02AB Aerospace Medical Service Apprentice Phase II, is approximately 6 weeks long. The course consists of 2 full days of orientation and then 28 days of clinical experience.

The purpose of this course is to enhance the clinical skills of the AMSA students by reinforcing knowledge, skills, and abilities gained during Phase I. Students will enhance their proficiency and build confidence in their nursing skills through repetition of skills.

This handbook is meant to be a quick reference regarding Eglin Phase II policies. This document is not meant to replace or dictate policies of the Air Force, but to enhance the learning atmosphere by providing generalized information and guidance for students to refer to when questions arise regarding acceptable behaviors while attached to the 96th Medical Group at Eglin AFB.',1,'INTRODUCTION',null),
('51000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000001','Pre & Post Conferences','**Pre-conference:**
- Held every first duty day of the week at 0730 in the AMSA classroom.
- All students will attend pre-conference unless they are involved in active patient care.

Pre-conference is to check accountability and to answer any questions students may have at that time. It is also the time to handout appointment slips for those who have appointments and to handle any issues that may arise.

**Post-conference:**
- Is held every first and last duty day at 1500 in the AMSA classroom.
- All students will attend post-conference unless they are involved in active patient care.

Post-conference is mainly time for the students. They share with the class what they learned at the specific duty sections they worked and may give feedback/ask questions they may have before the weekend. Additionally, we use this time to pass on pertinent information and upcoming grad requirements along with a safety brief.',2,'INTRODUCTION',null),
('51000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000001','Alcohol and Tobacco Use','**Alcohol Use:** The legal drinking age in Florida is 21. Students under the age of 21 will not consume alcoholic beverages, nor will those of age provide alcoholic beverages to underage students. Students suspected of reporting to duty with alcohol in their system are subject to a blood alcohol test. If of legal drinking age, students will not consume alcohol 12 hours prior to duty or prior to operating government vehicles.

**Tobacco Use:** The 96th Medical Group prohibits tobacco smoking (cigar, cigarette, pipe, etc.) and use of smokeless tobacco (spit/loose tobacco, electronic cigarettes, etc.) products on the hospital campus, to include outdoor areas and parking lots, by uniformed personnel. This policy is designed to protect the health of the hospital staff, students, visitors, and patients.',3,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000004','50000000-0000-0000-0000-000000000001','Dining Facility (DFAC) and Meal Times','**Breeze** - Phone Number (882-5019)
- Monday-Friday
- Breakfast: 0630-0900
- Lunch: 1030-1330
- Dinner: 1700-1900

**Hospital Dining Facility** - Phone Number (883-8547)
- Monday-Friday
- Breakfast: 0615-0730
- Lunch: 1100-1300

During the duty day, students will take the same breakfast or lunch as their preceptors. Eglin Hospital is closed campus breakfast/lunch, meaning students are not permitted to leave the facility to obtain meals unless authorized by the Course Supervisor.

For students working 12-hr shifts, breakfast and lunches will be grabbed "to-go" and eaten in the duty section breakroom. Training opportunities occur throughout the shift and students must be available for patient care opportunities in that section. Students working regular clinical shifts are authorized to eat meals in the seating area in the Dining Facility.

On hospital training days, the first Wednesday of every month, students working will be authorized to leave the hospital to get meals from the Breeze DFAC as the hospital DFAC is closed. Grabbing food "to-go" still applies.',4,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000005','50000000-0000-0000-0000-000000000001','Headphone, Mobile Phone, and Device Policy','Using listening devices impairs recognition of emergency signals, alarms, announcements, approaching vehicles, human speech, and other general noise. Therefore, wearing headphones or earphones on all installation roads and streets (except while traversing on sidewalks, not crosswalks) is prohibited. This includes, but is not limited to, operators of motorized vehicles or bicycles, joggers, walkers, and skaters. Phase II students will not wear headphones upon the ears, around the head or neck, or resting or dangling while in duty, dress, or physical fitness uniforms/gear. The only exception is that wearing headphones in physical fitness uniforms is authorized while actively conducting physical fitness in base gyms or on designated running tracks. Headphones will not be worn in organized physical fitness sessions.',5,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000006','50000000-0000-0000-0000-000000000001','Mandatory Items and Computer Use','Students are required to wear their issued hospital badge on the upper half of the uniform at all times. If the badge becomes lost, students must report the loss to the Course Supervisor immediately. Wearing the hospital badge off the hospital campus is strictly prohibited.

Students will maintain their student binder and keep it with them during the duty day.',6,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000007','50000000-0000-0000-0000-000000000001','Mobile Phone & Device Policy','Portable electronic devices can present distractions that negatively impact the delivery of the education mission. As such, portable electronic devices are not authorized and may not be used in the Phase II classroom (unless on meal break), patient care areas, or areas where instruction or training is being conducted.

Walking and talking on cell phones is prohibited while in any uniform. Driving a government vehicle and operating a handheld device is prohibited.

While on the hospital campus, students are authorized to have their cellphones on silent or off. Students are authorized to utilize their cell phones to reply to messages from their Course Supervisor, while on meal breaks, and when given written permission by the Course Supervisor when a situation deems it necessary.

Failure to comply with the cellphone policy can result in administrative action or removal of cellphone privileges on campus.',7,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000008','50000000-0000-0000-0000-000000000001','Computer Use','Students are not part of the Eglin Network, thus they are not authorized to login to any hospital computers. There is one exception: in the Phase II Classroom there is a computer designated for official use by students.

If students wish to print documents or utilize a computer off duty, there is a computer lab located at the Eglin Digital Library. The Library is located in the same building as Legends Sport Grill, located across from the Base Fitness Center by the Dorms.',8,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000009','50000000-0000-0000-0000-000000000001','Class Leader Program','The purpose of the Class Leader Program is to provide peer-to-peer mentorship and assistance to other students: report health, morale, and welfare concerns to the Course Supervisor; and develop leadership skills. Class Leaders have added responsibilities designated by the course supervisors, but their primary concern will still be the completion of training objectives.

Class leaders will be held to the highest standard and will relay messages and instructions from the Course Supervisor to their class as directed.',9,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000010','50000000-0000-0000-0000-000000000001','Class Absences/Appointments','An absence/appointment for any reason must be coordinated/approved by the Course Supervisor.

**Medical Appointments:** Students must make an acute appointment through the appointment line, 850-883-8600 (select option 1, option 1, option 1) for the Family Health Clinic. If it is an emergency, students can report to the Emergency Department. Regardless of the method, students must speak to a Course Supervisor first. For dental appointments, call 850-883-8324.

**Quarters:** If placed on quarters or hospitalized, students must notify the Course Supervisor immediately and bring a quarters slip from the provider. Students must have quarters in order to be dismissed from training.

**Leave:** Ordinary leave will not be approved during this course except during Exodus. Emergency leave will be granted as necessary. Emergency leave must be coordinated through the American Red Cross Agency.

**Tardiness Policy:** If a student is going to be late for a mandatory appointment, they must inform the course supervisor. Students are authorized to be tardy to mandatory appointments only if they are in patient care. To notify the Course Supervisor, students may call, text, or have their preceptor call or email the course supervisor.

**Ineffective Status:** If a student misses 8 consecutive hours of training for any reason, they will be placed on ineffective status until they return to training. It should be noted that missing more than 16 hours of training could cause the student''s graduation date to be held back.

- Appointments must not interfere with training, if at all possible.
- All administrative and medical appointments should be made during off duty time.
- Course Supervisor must confirm appointments during duty hours. You must request an appointment slip from your instructor on the morning of the appointment.
- Preceptors will not let you leave if you do not have an appointment slip. Students are required to make the preceptor aware of a scheduled appointment at the beginning of the shift. Preceptors will sign the appointment slip upon your return to the duty section.
- Students must turn the appointment slip in to the instructors. All missed time must be accounted for and will be required to be made up.
- Students who fail to make their instructor and preceptor aware of a scheduled appointment will be subjected to administrative action.',10,'GENERAL STUDENT INFORMATION AND GUIDANCE',null),
('51000000-0000-0000-0000-000000000011','50000000-0000-0000-0000-000000000001','General Customs','A custom is an established practice. Many military customs compliment procedures required by military courtesy. The breach of some customs merely brands the offender as ignorant, careless, or ill bred. Violations of other customs, however, will bring official censure or disciplinary action. The customs of the military are its common law. Below are a few examples.

- Never criticize the Military Services or a leader in public.
- Never go "over the heads" of superiors (AKA jumping the chain of command); you can ask/request to see your higher leadership if issues cannot be resolved at a lower leadership level.
- Never offer excuses.
- Never "wear" a superior''s rank by saying something like, "the first sergeant wants this done now," when in fact the first sergeant said no such thing — speak with your own voice.
- Never turn and walk away to avoid giving the hand salute or greeting of the day.
- If you don''t know the answer to a superior''s question, you will never go wrong with the response, "I don''t know sir/ma''am, but I''ll find out."',11,'CUSTOMS AND COURTESIES',null),
('51000000-0000-0000-0000-000000000012','50000000-0000-0000-0000-000000000001','General Courtesy','"Military" courtesy shows respect and reflects self-discipline. Consistent and proper military courtesy is an indicator of unit discipline, as well. Military members demonstrate courtesy in the way we address officers or NCOs of superior rank. Military courtesy is also the respect shown to each other by members of the same profession. Some of the Military''s more common courtesies include:

- Rendering the hand salute to an Officer or Greeting of the day to a more senior enlisted member.
- When talking to an officer of superior rank, standing at attention until ordered otherwise.
- Calling the classroom to standby when any NCO or SNCO enters the room and calling the classroom to attention when an officer enters or leaves the classroom.

If you don''t know the answer to a superior''s question, you will never go wrong with the response, "I don''t know sir/ma''am, but I''ll find out."',12,'CUSTOMS AND COURTESIES',null),
('51000000-0000-0000-0000-000000000013','50000000-0000-0000-0000-000000000001','Rendering Flag Honors','**Reveille:** When in uniform, upon hearing music (0730 daily), students will come to the position of parade rest for the first song. On the first note of the second song, students will come to the position of attention facing the flag (or sound of the music if flag is not visible) and render a salute until the final note is played.

**Retreat:** At retreat (1730 daily), when in uniform and not in formation, come to the position of attention facing the flag (or sound of the music if flag is not visible). Render the hand salute upon playing of "To the Colors". The salute is held through the last note of the music. If in civilian clothes, students come to attention and place the hand in front of the heart upon the playing of "To the Colors".',13,'CUSTOMS AND COURTESIES',null),
('51000000-0000-0000-0000-000000000014','50000000-0000-0000-0000-000000000001','Air Force Core Values','**Integrity First:** the willingness to do what is right even when no one is looking. It is the "moral compass", the inner voice, the voice of self-control, and the basis for the trust imperative in today''s military. It includes courage, honesty, responsibility, accountability, justice, openness, self-respect, and humility.

**Service Before Self:** tells us that professional duties take precedence over personal desires. It includes role following, respect for others, discipline and self-control, and faith in the system.

**Excellence In All We Do:** directs us to develop a sustained passion for continuous improvement and innovation that will propel the Air Force into a long-term, upward spiral of accomplishment and performance.',14,'CUSTOMS AND COURTESIES',null),
('51000000-0000-0000-0000-000000000015','50000000-0000-0000-0000-000000000001','General Uniform Guidance',null,15,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000016','50000000-0000-0000-0000-000000000001','Food and Beverages','All Phase II students are prohibited from walking and/or eating (including chewing gum) while in uniform.',16,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000017','50000000-0000-0000-0000-000000000001','General Uniform Appearance and Guidance','All students will keep uniforms buttoned and in serviceable condition. While in uniform, students may not place their hands in their pockets unless momentarily to place or retrieve objects.',17,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000018','50000000-0000-0000-0000-000000000001','Backpacks','Students'' backpacks will be solid black, olive drab, Air Force sage green, or Airman Battle Uniform (ABU) pattern in color and may be worn with any uniform combination. Small logos are authorized. Airmen may wear a backpack on the left shoulder or both shoulders (so as not to interfere with rendering the proper salute). Backpacks will not have ornamentation, a high-gloss finish, designs, or hanging/dangling objects. Exception: water bottles may be attached to the outside of the bag. Small gold or silver clasps are authorized, but chains are not authorized. Gym bags will be solid dark-blue, black, olive drab, Air Force sage green, or ABU pattern with matching stitching and carried in the left hand. Use of a shoulder strap is authorized on the left shoulder and the strap may cross the body as long as it does not interfere with rendering the proper salute. Small logos are authorized.',18,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000019','50000000-0000-0000-0000-000000000001','Body Alterations (Body Piercing/Alterations)','Cannot attach, affix, or display objects/jewelry to or through the ear, nose, tongue, or any exposed body part (including those visible through the uniform). Exception: women may wear one pair of earrings as described below. Males may not wear earrings on a military installation, while in uniform, or in civilian attire for official duty. Females may wear one small (not to exceed 6 mm in diameter) spherical, conservative, diamond, gold, white pearl, or silver earring set with any uniform combination. Earrings should fit tightly without extending below the earlobe unless the extending piece is the connecting band on clip earrings.',19,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000020','50000000-0000-0000-0000-000000000001','Cosmetics','Males may not wear cosmetics. Females may wear cosmetics that are conservative (not excessive or extreme) and in good taste. Will not wear lipstick that contrasts with their complexion, that detracts from the uniform, or that is extreme in color. Examples of extreme colors include, but are not limited to: purple, gold, blue, black, bright red, and fluorescent colors. Cosmetics will not be worn during field conditions.',20,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000021','50000000-0000-0000-0000-000000000001','Eye Glasses/Sunglasses/Contacts','Eyeglasses and sunglasses must be worn in the manner for which they are made. They will not be worn around the neck, on top or back of the head, or hanging exposed on the uniform. Frames and lenses must be conservative. Faddish styles or mirrored lenses are prohibited. Sunglasses are not authorized in formation unless for medical purposes. Contact lenses that change the natural eye color are not authorized.',21,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000022','50000000-0000-0000-0000-000000000001','Fingernails','Males may not wear nail polish. If worn by females, nail polish will be a single color that does not distinctly contrast with the female Airman''s complexion, detract from the uniform, or be an extreme color. Fingernails cannot exceed 1/4 inch beyond the tip of the finger and must be clean and well-groomed. White-tip French manicure is authorized.',22,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000023','50000000-0000-0000-0000-000000000001','Hair General','Must be clean, well-groomed, and not: contain excessive grooming aids, appear lopsided, or touch either eyebrow. Hair may be dyed, but must be a natural color.',23,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000024','50000000-0000-0000-0000-000000000001','Hair Male','Must have tapered appearance. Will not exceed 1 1/4" in bulk, regardless of length, and 1/4" at termination point, allowing only closely cut or shaven hair on the back of the neck to touch the collar. Hair will not touch ears or protrude under the front band of headgear. Cleanly shaven, high-and-tight, and flat-top cuts are authorized. Men are not authorized mohawks, mullets, cornrows, dreadlocks, etched designs, or hair extensions.',24,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000025','50000000-0000-0000-0000-000000000001','Hair Female','Minimum hair length is 1/4 inch, to a maximum bulk of three inches from the scalp, and allows proper wear of headgear. Hair will end above the bottom edge of the collar and will not extend below an invisible line drawn parallel to the ground, both front to back and side to side. Bangs or side-swept hair will not touch either eyebrow.

- When hair is in a bun, the bun must be a single bun, no wider than the width of the head, with all loose ends tucked in and secured.
- When hair is in a ponytail, it must be a single ponytail that does not exceed bulk and length standards and does not extend below the bottom of the collar (except while in the PTU).
- Hair accessories, if worn, must match the hair color and comply with bulk and appearance standards; headbands or fabric scrunchies will not exceed one inch in width, and ornaments are not authorized.
- Braids, twists, micro-braids, French braids, Dutch braids, and cornrows are authorized, provided they are conservative, natural looking, and comply with bulk and length standards.

Hair color, highlights, lowlights, and frosting will not be faddish or extreme and will be a natural looking hair color similar to the individual''s hair color.',25,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000026','50000000-0000-0000-0000-000000000001','Hospital Scrubs','When working in work centers authorized to wear scrubs, both top and bottoms must be worn. The tan t-shirt will be worn and will be tucked in. Sleeves will not extend past the scrub shirt. Scrubs can be found next to or in the locker rooms of the work centers.

The Blues name tag and rank insignia must be worn on the outside of the scrubs on the right side of the scrub top. The metal rank will be centered 1/2 inch above the name tag.

Authorized footwear includes sage green boots and socks, as well as any combination of shoes and socks authorized for PT gear in AFI 36-2903.

A scrub jacket is required to be worn, if available, when leaving the duty section or going into the Operating Room.

At no point in time are scrubs authorized to be worn outside of the hospital building — students must change back into ABUs if they need to go outside. This is for infection control standards.',26,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000027','50000000-0000-0000-0000-000000000001','ABUs',null,27,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000028','50000000-0000-0000-0000-000000000001','Service Dress',null,28,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000029','50000000-0000-0000-0000-000000000001','PT Gear',null,29,'UNIFORMS',null),
('51000000-0000-0000-0000-000000000030','50000000-0000-0000-0000-000000000001','Duty Hours','Students'' hours here at Eglin Hospital will vary depending on the duty section they are assigned to. The normal clinical rotation will be Monday through Friday on 8-hour rotations. If working in the inpatient units or the ER, students work 12-hour shifts with respective days off. Students are not permitted to ask preceptors to be released early. If a preceptor releases a student early, they must report to the course supervisor immediately or have the preceptor call. Students are in a learning environment and time to master patient care skills will not be compromised.

Duty hours listed in the AMSA Phase II Student Schedule Key are required times. Students must be in the designated duty section at the listed start time and may not be released until the listed stop time. Phase II students will not be on night shift unless extreme circumstances require it.',30,'AMSA PHASE II CLINICAL ROTATIONS',null),
('51000000-0000-0000-0000-000000000031','50000000-0000-0000-0000-000000000001','AMSA Phase II Student Schedule Key',null,31,'AMSA PHASE II CLINICAL ROTATIONS','{"headers": ["Duty Section", "Days", "Day Shift Hours", "Night Shift Hours", "Uniform"], "rows": [["Family Health Clinic (FHC)", "M-F", "0730-1445", "N/A", "ABU"], ["Family Medicine Residency Clinic (FMRC)", "M-F", "0730-1445", "N/A", "ABU"], ["Pediatric Clinic (PEDS)", "M-F", "0730-1445", "N/A", "ABU"], ["OB/GYN Clinic (OB/GYN)", "M-F", "0730-1445", "N/A", "ABU"], ["Flight and Operational Medicine (FOMC)", "M-F", "0730-1445", "N/A", "ABU"], ["Immunization Clinic (IMM)", "M-F", "0730-1445", "N/A", "ABU"], ["General Surgery Clinic (GS)", "M-F", "0730-1445", "N/A", "ABU"], ["Dermatology Clinic (DERM)", "M-F", "0730-1445", "N/A", "ABU"], ["Orthopedic Clinic (ORTHO)", "M-F", "0730-1445", "N/A", "ABU"], ["GI Clinic (GI)", "M-F", "0730-1445", "N/A", "ABU"], ["Neurology Clinic (NEURO)", "M-F", "0730-1445", "N/A", "ABU"], ["Internal Medicine Clinic (IM)", "M-F", "0730-1445", "N/A", "ABU"], ["Cardiology Clinic (CARDIO)", "M-F", "0730-1445", "N/A", "ABU"], ["Warrior Operational Medicine Clinic (WOMC)", "M-F", "0730-1445", "N/A", "ABU"], ["Ambulatory Surgical Unit (ASU)", "M-F", "0730-1445", "N/A", "Scrubs"], ["Operating Room (OR)", "M-F", "0730-1445", "N/A", "Scrubs"], ["Intensive Care Unit (ICU)", "M-F", "0530-1745", "1745-0545", "ABU/Scrubs"], ["Multi Service Unit (MSU)", "M-F", "0530-1745", "1745-0545", "ABU/Scrubs"], ["Labor and Delivery (L&D)", "M-F", "0530-1745", "1745-0545", "ABU/Scrubs"], ["Emergency Room (ER)", "M-F", "0530-1745", "1745-0545", "ABU"]]}'::jsonb)
on conflict (id) do update set heading=excluded.heading, body=excluded.body, sort_order=excluded.sort_order, section_group=excluded.section_group, table_data=excluded.table_data;

