-- FAQs. Global entries apply everywhere; Eglin entries reflect that location's current guidance.
insert into public.faqs (id,location_id,question,answer,sort_order,is_active) values
('80000000-0000-0000-0000-000000000001',null,'How do I get access after I sign up?','A Phase II supervisor reviews your requested role and location, then approves your account. You will see your status on the pending-approval page and gain access to your dashboard once approved.',1,true),
('80000000-0000-0000-0000-000000000002',null,'How do kudos get published?','Submitted kudos are reviewed by a supervisor before they appear publicly. Once approved, they are published to the department gallery with the star rating you gave.',2,true),
('80000000-0000-0000-0000-000000000003',(select id from public.locations where installation_code='EGLIN'),'Where do I report on my first day?','Students begin Phase II with a full orientation day in the classroom, not in the clinics.',10,true),
('80000000-0000-0000-0000-000000000004',(select id from public.locations where installation_code='EGLIN'),'What uniform do I wear on Day 1?','Service Dress Blues are required for orientation; clinic-specific uniforms begin on Day 2.',11,true),
('80000000-0000-0000-0000-000000000005',(select id from public.locations where installation_code='EGLIN'),'What should I bring to orientation?','Notebook, CAC, water, and required paperwork.',12,true),
('80000000-0000-0000-0000-000000000006',(select id from public.locations where installation_code='EGLIN'),'What do I do if I''m sick?','If you feel sick during Phase II, the first step is always to notify your supervisor. They will determine whether you need an appointment slip for a same-day visit or if you should be evaluated more urgently. If your symptoms are mild, your supervisor will direct you to schedule a routine appointment. If you are really sick, experiencing worsening symptoms, or unable to safely participate in training, you must talk to your supervisor immediately so they can send you to the ER or WOMC for evaluation. Students should never self-diagnose, skip reporting procedures, or attempt to work while ill. Proper reporting protects you, your patients, and the mission.',13,true),
('80000000-0000-0000-0000-000000000007',(select id from public.locations where installation_code='EGLIN'),'Transportation & getting around Eglin AFB','Students at Eglin AFB have access to a base-use van that can be used for group trips to approved on-base locations. The van is meant to help students move safely and efficiently without needing personal vehicles. If you want to go somewhere like the BX, Commissary, or the on-base beach, you can coordinate with your classmates and supervisor to use the van. Students can also volunteer to drive their own vehicle so more people can go, as long as everyone communicates clearly and follows safety expectations. The van is for on-base use only, and students must stay within approved areas and return on time. Good communication ensures everyone gets what they need while staying accountable and safe.',14,true),
('80000000-0000-0000-0000-000000000008',(select id from public.locations where installation_code='EGLIN'),'Rules for using personal vehicles in Phase II','Using a personal vehicle during Phase II is allowed, but it comes with expectations to ensure safety, accountability, and professionalism. Students must always communicate their plans and follow base and program rules. Personal vehicles cannot be used to travel to and from the hospital, dorms, or to leave base during training hours unless approved. Students are expected to follow all traffic laws, maintain proper insurance, and represent the program professionally while driving on base.',15,true),
('80000000-0000-0000-0000-000000000009',(select id from public.locations where installation_code='EGLIN'),'Fun things to do on Eglin AFB (safely)','Eglin AFB has plenty of places for students to relax, explore, and have fun without leaving base. Students can use the base van (on-base only) or coordinate rides with classmates to visit approved locations. Safety, communication, and accountability always come first.

- **Fitness Centers**: multiple gyms with weight rooms, cardio equipment, basketball courts, and group fitness classes — great for stress relief and staying mission-ready.
- **Trails & Outdoor Areas**: walking trails, picnic areas, and scenic spots perfect for relaxing or getting fresh air between study sessions.
- **On-Base Beach**: beautiful, quiet beaches located inside the base where students can relax, swim, walk, or hang out as a group.',16,true),
('80000000-0000-0000-0000-000000000010',(select id from public.locations where installation_code='EGLIN'),'Fun things to do outside Eglin AFB (safely)','Eglin AFB is surrounded by some of the most beautiful beaches, restaurants, and attractions in Florida. Students are allowed to explore off-base during off-duty hours, as long as they follow safety rules, stay in groups, and maintain professionalism. Personal vehicles are required for off-base trips — the van cannot leave base.

- [Destin & Fort Walton Beach](https://www.destinfwb.com/): known for white-sand beaches, restaurants, and shops — great for group outings, sunsets, or grabbing food.
- [The Boardwalk on Okaloosa Island](https://www.myokaloosa.com/parks/boardwalk): a popular spot with restaurants, ice cream, volleyball, and a pier.
- **Restaurants & Cafes**: Destin and FWB have tons of food options — seafood, pizza, coffee shops, and casual dining.
- **Bowling, Mini Golf & Arcades**: fun, safe group activities that don''t involve alcohol and keep everyone together.
- **Water Activities**: kayaking, paddleboarding, dolphin tours, and boat rentals are available in Destin — students must follow all safety rules and stay in groups.
- [Destin Commons](https://destincommons.com/) and [Silver Sands Outlet Mall](https://www.destinflorida.com/destin/shopping/shopping-center/silver-sand-premium-outlets): popular for shopping, walking around, and grabbing food.',17,true)
on conflict (id) do update set question=excluded.question, answer=excluded.answer, sort_order=excluded.sort_order, is_active=true;

commit;
